// Mapbox public browser token. Generated at install/build; never commit this generated file.
import { existsSync, mkdirSync, writeFileSync } from 'node:fs';
const localEnvironment = new URL('../.env.local', import.meta.url);
if (existsSync(localEnvironment)) process.loadEnvFile(localEnvironment);
const token = process.env.MAPBOX_TOKEN?.trim() ?? '';
if (token && !/^pk\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$/.test(token)) {
  throw new Error('MAPBOX_TOKEN debe ser un token público de Mapbox (pk.).');
}
mkdirSync(new URL('../src/environments/', import.meta.url), { recursive: true });
writeFileSync(
  new URL('../src/environments/mapbox-token.ts', import.meta.url),
  '// Generated by scripts/set-mapbox-token.mjs.\nexport const MAPBOX_TOKEN = ' +
    JSON.stringify(token) +
    ';\n',
  { mode: 0o600 },
);
console.log(
  token
    ? 'Mapbox: token público configurado.'
    : 'Mapbox: sin token; se mostrará la ubicación de respaldo.',
);
